-- V11__role_permissions_fix.sql
-- Grant missing permissions to REGIONAL_ADMIN, STATION_ADMIN, and REPORT_REVIEWER

-- REGIONAL_ADMIN PERMISSIONS
ON CONFLICT (role_id, permission_id) DO NOTHING;

-- STATION_ADMIN PERMISSIONS
ON CONFLICT (role_id, permission_id) DO NOTHING;

-- REPORT_REVIEWER PERMISSIONS
ON CONFLICT (role_id, permission_id) DO NOTHING;
